select case when s.rating >= 4.2 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end as rating_bucket, avg(ss.units) as avg_units, max(ss.sale_date) as last_sale_date from store_sales ss inner join products p on ss.product_id = p.id left join suppliers s on p.supplier_id = s.id where s.rating > 3.4 group by case when s.rating >= 4.2 then 'high' when s.rating >= 1.6 then 'mid' else 'low' end order by avg_units;
